// Configure your competitors and news sources
const config = {
  competitors: [
    { name: 'Competitor A', domain: 'competitor-a.com', blog_rss: 'https://competitor-a.com/blog/rss.xml', twitter: '@competitorA' },
    { name: 'Competitor B', domain: 'competitor-b.com', blog_rss: 'https://competitor-b.com/rss', twitter: '@competitorB' },
    { name: 'Competitor C', domain: 'competitor-c.com', blog_rss: 'https://competitor-c.com/feed', twitter: '@competitorC' }
  ],
  news_queries: [
    'your_industry_keyword product launch',
    'your_industry_keyword funding',
    'your_industry_keyword pricing',
    'your_industry_keyword acquisition'
  ],
  digest_recipients: [
    'ceo@REPLACE_YOUR_DOMAIN.com',
    'product@REPLACE_YOUR_DOMAIN.com',
    'sales@REPLACE_YOUR_DOMAIN.com'
  ],
  slack_channel: '#competitive-intel',
  week_start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
};

return [{ json: config }];

// Merge data from all 3 input streams
const competitorAItems = $input.all().filter(i => i.json.link || i.json.url).slice(0, 5);

const articles = [];

for (const item of competitorAItems) {
  articles.push({
    source_type: 'competitor_blog',
    competitor: 'Competitor A',
    title: item.json.title ?? '',
    url: item.json.link ?? item.json.url ?? '',
    summary: item.json.contentSnippet ?? item.json.description ?? '',
    published_at: item.json.pubDate ?? item.json.isoDate ?? new Date().toISOString()
  });
}

return [{ json: { articles, total_articles: articles.length, week_start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], generated_at: new Date().toISOString() } }];

