const raw = $input.item.json.message?.content ?? '{}';
let digest;
try { digest = JSON.parse(raw); }
catch(e) { 
  const match = raw.match(/\{[\s\S]*\}/);
  try { digest = JSON.parse(match?.[0] ?? '{}'); }
  catch { digest = { executive_summary: 'AI analysis unavailable this week.', key_threats: [], opportunities: [], competitor_highlights: [], market_trends: [], action_items: [] }; }
}

const prevData = $input.item.json;

// Build HTML email
const formatSection = (title, items, formatter) => {
  if (!items?.length) return '';
  return `<h2 style="color:#1a1a2e;border-bottom:2px solid #e63946;padding-bottom:8px">${title}</h2>` +
    items.map(formatter).join('');
};

const emailHtml = `
<div style="font-family:Arial,sans-serif;max-width:800px;margin:0 auto">
  <div style="background:#1a1a2e;color:white;padding:24px;border-radius:8px 8px 0 0">
    <h1 style="margin:0;font-size:24px">Weekly Competitive Intelligence Digest</h1>
    <p style="margin:8px 0 0;opacity:0.8">Week of ${prevData.week_start} · Generated ${prevData.generated_at?.split('T')[0]}</p>
  </div>
  <div style="background:#f8f9fa;padding:24px">
    <div style="background:white;padding:20px;border-radius:8px;margin-bottom:20px;border-left:4px solid #e63946">
      <h2 style="color:#1a1a2e;margin-top:0">Executive Summary</h2>
      <p style="line-height:1.6;color:#333">${digest.executive_summary ?? 'No summary available.'}</p>
    </div>
    ${digest.key_threats?.length ? `
    <div style="background:white;padding:20px;border-radius:8px;margin-bottom:20px">
      <h2 style="color:#e63946;margin-top:0">🚨 Key Threats</h2>
      ${digest.key_threats.map(t => `<div style="padding:12px;background:#fff5f5;border-radius:4px;margin-bottom:8px">
        <strong>${t.competitor}</strong>: ${t.threat}<br/>
        <span style="color:#e63946;font-size:12px">Urgency: ${t.urgency?.toUpperCase()}</span> · 
        <span style="color:#666;font-size:12px">Response: ${t.recommended_response}</span>
      </div>`).join('')}
    </div>` : ''}
    ${digest.opportunities?.length ? `
    <div style="background:white;padding:20px;border-radius:8px;margin-bottom:20px">
      <h2 style="color:#2ecc71;margin-top:0">✅ Opportunities</h2>
      ${digest.opportunities.map(o => `<div style="padding:12px;background:#f0fff4;border-radius:4px;margin-bottom:8px">
        <strong>${o.opportunity}</strong><br/>
        <span style="color:#666;font-size:13px">${o.evidence}</span><br/>
        <span style="color:#2ecc71;font-size:13px;font-weight:bold">→ ${o.action}</span>
      </div>`).join('')}
    </div>` : ''}
    ${digest.action_items?.length ? `
    <div style="background:white;padding:20px;border-radius:8px;margin-bottom:20px">
      <h2 style="color:#1a1a2e;margin-top:0">📋 Action Items</h2>
      ${digest.action_items.map(a => `<div style="padding:8px;border-bottom:1px solid #eee">
        <strong style="color:#e63946">[${a.owner}]</strong> ${a.action} <span style="color:#999;font-size:12px">(${a.deadline})</span>
      </div>`).join('')}
    </div>` : ''}
  </div>
</div>`;

return {
  ...prevData,
  digest,
  email_html: emailHtml,
  week_start: prevData.week_start
};
